mapper.select:
select t1.id, t1.name, t1.no, t1.phone, t1.violation_count, t1.violation_score, t1.update_time, t2.name as clazz_name, ( case t1.degree when 1 then '初中' when 2 then '高中' when 3 then '大专' when 4 then '本科' when 5 then '硕士' when 6 then '博士' else '其他' end ) as degree, ( case t1.gender when 1 then '男' when 2 then '女' else '其他' end ) as gender from student t1 left join clazz t2 on t1.clazz_id = t2.id
t1.name like CONCAT('%', #{name}, '%')
t1.degree = #{degree}
t1.clazz_id = #{clazzId}
order by t1.id desc
